import { progressionGrant } from "./progression-features.js";

const STAGE_LEVELS = Object.freeze([1, 16, 26]);

const evolution = (id, name, stage) => progressionGrant("evolution", id, { name, stage, source: "racial-progression" });
const ability = (id) => progressionGrant("ability", id, { innate: true, source: "racial-progression" });
const passive = (id, name, description) => progressionGrant("passive", id, { name, description, source: "racial-progression" });
const action = (id, name, description) => progressionGrant("action", id, { name, description, source: "racial-progression", racialCapability: true });
const lesson = (name, description, ...grants) => Object.freeze({ name, description, grants: Object.freeze(grants) });

function authoredTrack(raceId, rows) {
  if (rows.length !== 30) throw new Error(`${raceId} racial progression must author exactly 30 levels; received ${rows.length}`);
  return Object.freeze(rows.map((entry, index) => {
    const level = index + 1;
    const practicedFeature = progressionGrant("proficiency", `${raceId}:racial-level-${level}`, {
      name: entry.name,
      description: entry.description,
      source: "racial-progression",
    });
    return Object.freeze({
      level,
      name: entry.name,
      description: entry.description,
      grants: Object.freeze([practicedFeature, ...entry.grants]),
    });
  }));
}

function racialProfile(name, stages, attributes, progression) {
  const granted = progression.flatMap((row) => row.grants);
  return Object.freeze({
    name,
    stages: Object.freeze(stages),
    stageLevels: STAGE_LEVELS,
    evolutionStages: Object.freeze(stages.map((stageName, index) => Object.freeze({
      level: STAGE_LEVELS[index],
      name: stageName,
      id: String(stageName).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, ""),
    }))),
    evolution: stages.at(-1),
    attributes: Object.freeze(attributes),
    progression,
    abilities: Object.freeze([...new Set(granted.filter((grant) => grant.type === "ability").map((grant) => grant.id))]),
    passives: Object.freeze([...new Set(granted.filter((grant) => grant.type === "passive").map((grant) => grant.id))]),
  });
}

