export const RACIAL_PROFILES = Object.freeze({
  human: racialProfile("Human", ["Mortal", "Limit Breaker", "Mortal Transcendent"], ["wit", "presence", "vigor", "mind"], HUMAN_PROGRESSION),
  elf: racialProfile("Elf", ["Elf", "Elder Elf", "High Elf"], ["reflex", "mind", "wit", "presence"], ELF_PROGRESSION),
  dwarf: racialProfile("Dwarf", ["Dwarf", "Deep Dwarf", "Deep Elder"], ["vigor", "body", "wit", "mind"], DWARF_PROGRESSION),
  halfling: racialProfile("Small Folk", ["Small Folk", "Hearth Keeper", "Hearth Elder"], ["reflex", "wit", "presence", "vigor"], HALFLING_PROGRESSION),
  "half-orc": racialProfile("Half-Orc", ["Half-Orc", "Warblood", "Warblood Ascendant"], ["body", "vigor", "presence", "reflex"], HALF_ORC_PROGRESSION),
  orc: racialProfile("Orc", ["Orc", "High Orc", "Orc Elder"], ["body", "vigor", "presence", "wit"], ORC_PROGRESSION),
  goblin: racialProfile("Goblin", ["Goblin", "Hobgoblin", "Goblin Elder"], ["reflex", "wit", "vigor", "mind"], GOBLIN_PROGRESSION),
  drakeborn: racialProfile("Drake-Blooded", ["Drake-Blooded", "Wyrm-Blooded", "Dragon Ascendant"], ["vigor", "presence", "body", "mind"], DRAKEBORN_PROGRESSION),
  beastfolk: racialProfile("Beast Folk", ["Beast Folk", "Primal Blood", "Primal Exemplar"], ["reflex", "vigor", "body", "wit"], BEASTFOLK_PROGRESSION),
  demonborn: racialProfile("Demon-Blooded", ["Demon-Blooded", "Greater Demon-Blooded", "True Demon"], ["presence", "mind", "vigor", "body"], DEMONBORN_PROGRESSION),
  vampire: racialProfile("Vampire", ["Lesser Vampire", "Vampire", "True Vampire"], ["reflex", "vigor", "presence", "body"], VAMPIRE_PROGRESSION),
  lycanthrope: racialProfile("Lycanthrope", ["Fledgling Lycanthrope", "Lycanthrope", "True Lycanthrope"], ["body", "vigor", "reflex", "wit"], LYCANTHROPE_PROGRESSION),
  wyrm: racialProfile("Wyrm", ["Young Wyrm", "Elder Wyrm", "Ancient Wyrm"], ["vigor", "body", "presence", "mind"], WYRM_PROGRESSION),
  demon: racialProfile("Demon", ["Lesser Demon", "Greater Demon", "Archdemon"], ["presence", "mind", "vigor", "body"], DEMON_PROGRESSION),
  fae: racialProfile("Fae", ["Lesser Fae", "Fae", "High Fae"], ["presence", "mind", "reflex", "wit"], FAE_PROGRESSION),
});

export function racialProfileFor(raceId) {
  const id = String(raceId || "").toLowerCase();
  return RACIAL_PROFILES[id] || null;
}

export function racialProgressionRows(raceId) {
  return racialProfileFor(raceId)?.progression || Object.freeze([]);
}

export function racialProgressionAtLevel(raceId, level) {
  const bounded = Math.max(1, Math.min(30, Math.floor(Number(level) || 1)));
  return racialProgressionRows(raceId)[bounded - 1] || null;
}
